'use strict';
const ILLUSTRATION_NAMES={'school-items':'en bok, en penn, en sekk og en telefon','hold-book':'en person holder en bok','hold-pen':'en person holder en penn','pen-blue':'en blå penn','dots1':'én prikk','dots2':'to prikker','dots3':'tre prikker','book-sizes':'en stor bok og en liten bok','book-red':'en rød bok','book-blue':'en blå bok','book-green':'en grønn bok','big-book':'en stor bok','small-book':'en liten bok',books1:'én bok',books2:'to bøker',books3:'tre bøker',book:'en bok',pen:'en penn',table:'et bord',chair:'en stol',bag:'en sekk',phone:'en telefon',person:'en person',pair:'to personer',read:'en person leser',write:'en person skriver',school:'en skole','book-on-table':'en bok på et bord','book-under-table':'en bok under et bord','book-in-bag':'en bok i en sekk',eat:'en person spiser',clock8:'klokka åtte',clock12:'klokka tolv',clock18:'klokka seks, her 06.00',calendar:'en kalender',self:'to personer: jeg viser til den som snakker',you:'to personer: du viser til den som blir snakket til',tomorrow:'en pil fra i dag til i morgen',monday:'en kalender der mandag er markert',tuesday:'en kalender der tirsdag er markert'};
function illustration(id,decorative=false){
 const book=(x=72,y=60,width=100,height=112,color='#aa4f36')=>`<rect x="${x+3}" y="${y+5}" width="${width}" height="${height}" rx="4" fill="#e2d6bc" stroke="#293c37"/><rect x="${x}" y="${y}" width="${width}" height="${height}" rx="4" fill="${color}" stroke="#293c37" stroke-width="2"/><path d="M${x+12} ${y}v${height}" stroke="#713b2b" stroke-width="2"/><path d="M${x+31} ${y+28}h${width-49}M${x+31} ${y+35}h${width-49}" stroke="#f5e3bd" stroke-width="2"/><rect x="${x+30}" y="${y+49}" width="${width-48}" height="${height/3}" fill="#c97857"/>`;
 const table=`<path d="M44 100h170l-12 19H32z" fill="#c5a47b" stroke="#293c37" stroke-width="2"/><path d="M47 120v71M189 120v71" stroke="#293c37" stroke-width="7"/><path d="M50 133h138" stroke="#977b59" stroke-width="4"/>`;
 const person=`<circle cx="125" cy="58" r="25" fill="#d9b995" stroke="#293c37" stroke-width="2"/><path d="M101 51q4-34 29-22 20 7 17 33l-12-20-17 7z" fill="#3c4038"/><path d="M76 178l9-69q7-23 40-23 35 0 42 23l8 69z" fill="#7b918a" stroke="#293c37" stroke-width="2"/><path d="M99 119v55M151 119v55" stroke="#293c37" stroke-width="2"/>`;
 const bag=`<path d="M92 63v-8q0-26 31-26t31 26v8" fill="none" stroke="#293c37" stroke-width="8"/><rect x="66" y="58" width="117" height="137" rx="26" fill="#798d83" stroke="#293c37" stroke-width="2"/><rect x="83" y="117" width="83" height="57" rx="12" fill="#b5c1ac" stroke="#293c37" stroke-width="2"/><path d="M88 131h71M72 94h107" stroke="#293c37" stroke-width="2"/>`;
 let shape='';
 switch(id){
 case 'hold-book':shape=person+book(92,110,66,74)+`<path d="M86 127l12 22M162 127l-12 22" stroke="#d9b995" stroke-width="10" stroke-linecap="round"/>`;break;
 case 'hold-pen':shape=person+`<g transform="rotate(25 142 120)"><path d="M138 68h10v93l-5 12-5-12z" fill="#527f9d" stroke="#293c37" stroke-width="2"/><path d="M138 161h10l-5 12z" fill="#e9dfcb" stroke="#293c37"/></g><path d="M91 127l37 25 13-22" stroke="#d9b995" fill="none" stroke-width="10" stroke-linecap="round"/>`;break;
 case 'school-items':shape=`<rect x="20" y="55" width="66" height="83" rx="3" fill="#aa4f36" stroke="#293c37" stroke-width="2"/><path d="M29 55v83M43 78h30" stroke="#f5e3bd" stroke-width="2"/><path d="M102 48h8v92l-4 10-4-10z" fill="#527f9d" stroke="#293c37" stroke-width="2"/><rect x="125" y="68" width="52" height="72" rx="12" fill="#798d83" stroke="#293c37" stroke-width="2"/><path d="M137 68v-7q0-15 14-15t14 15v7M134 111h34v19h-34z" fill="none" stroke="#293c37" stroke-width="2"/><rect x="193" y="58" width="38" height="76" rx="6" fill="#3b5552" stroke="#293c37" stroke-width="2"/><rect x="198" y="68" width="28" height="53" fill="#c4d1c0"/>`;break;
 case 'pen-blue':shape=`<g transform="rotate(30 125 110)"><path d="M116 35h18v138l-9 22-9-22z" fill="#527f9d" stroke="#293c37" stroke-width="2"/><path d="M116 173h18l-9 22z" fill="#e9dfcb" stroke="#293c37"/><path d="M121 184l4 11 5-11z" fill="#293c37"/><path d="M133 40h9v39" fill="none" stroke="#293c37" stroke-width="3"/></g>`;break;
 case 'dots1':case 'dots2':case 'dots3':{const n=Number(id.at(-1));shape=Array.from({length:n},(_,i)=>`<circle cx="${125+(i-(n-1)/2)*65}" cy="110" r="22" fill="#aa4f36" stroke="#293c37" stroke-width="2"/>`).join('');break;}
 case 'book-sizes':shape=book(30,45,100,130)+book(160,102,55,73,'#527f9d');break;
 case 'book':case 'book-red':shape=book();break;
 case 'book-blue':shape=book(72,60,100,112,'#527f9d');break;
 case 'book-green':shape=book(72,60,100,112,'#648968');break;
 case 'big-book':case 'small-book':{const x=id==='big-book'?80:188;shape=book(30,45,100,130)+book(160,102,55,73,'#527f9d')+`<path d="M${x} 14v20m-7-7 7 7 7-7" stroke="#a64b30" stroke-width="4" fill="none"/>`;break;}
 case 'books1':shape=book(88,72,74,88);break;
 case 'books2':shape=book(42,72,74,88)+book(134,72,74,88,'#527f9d');break;
 case 'books3':shape=book(16,80,60,74)+book(95,80,60,74,'#527f9d')+book(174,80,60,74,'#648968');break;
 case 'pen':shape=`<g transform="rotate(30 125 110)"><path d="M116 35h18v138l-9 22-9-22z" fill="#e2bc64" stroke="#293c37" stroke-width="2"/><path d="M116 47h18v19h-18z" fill="#537c79"/><path d="M116 173h18l-9 22z" fill="#e9dfcb" stroke="#293c37"/><path d="M121 184l4 11 5-11z" fill="#293c37"/><path d="M133 40h9v39" fill="none" stroke="#293c37" stroke-width="3"/></g>`;break;
 case 'table':shape=table;break;
 case 'chair':shape=`<rect x="79" y="39" width="90" height="69" rx="8" fill="#78918a" stroke="#293c37" stroke-width="2"/><path d="M85 108v32M163 108v32" stroke="#293c37" stroke-width="5"/><path d="M72 140h104v15H72z" fill="#c8af87" stroke="#293c37" stroke-width="2"/><path d="M80 156v44M169 156v44" stroke="#293c37" stroke-width="6"/>`;break;
 case 'bag':shape=bag;break;
 case 'phone':shape=`<rect x="84" y="24" width="84" height="175" rx="13" fill="#3b5552" stroke="#293c37" stroke-width="2"/><rect x="91" y="42" width="70" height="131" rx="2" fill="#c4d1c0"/><path d="M116 33h21" stroke="#eee7d5" stroke-width="3"/><circle cx="126" cy="185" r="5" stroke="#eee7d5" fill="none"/>`;break;
 case 'self':case 'you':{const x=id==='self'?72:178;shape=`<g transform="translate(-24 25) scale(.75)">${person}</g><g transform="translate(83 25) scale(.75)">${person}</g><path d="M${x} 25v22m-6-6 6 6 6-6" fill="none" stroke="#a64b30" stroke-width="3"/><rect x="${x-25}" y="0" width="50" height="22" rx="3" fill="#aa4f36"/><text x="${x}" y="16" text-anchor="middle" font-family="Arial" font-size="12" fill="#fff8e9">${id==='self'?'JEG':'DU'}</text>`;break;}
 case 'tomorrow':shape=`<rect x="25" y="64" width="87" height="104" fill="#fff8e9" stroke="#293c37"/><rect x="139" y="64" width="87" height="104" fill="#e0e8d5" stroke="#293c37"/><path d="M25 64h87v24H25zM139 64h87v24h-87z" fill="#aa4f36"/><text x="68" y="127" font-size="16" font-family="Arial" text-anchor="middle" fill="#293c37">i dag</text><text x="183" y="127" font-size="16" font-family="Arial" text-anchor="middle" fill="#293c37">i morgen</text><path d="M112 114h25m-6-6 6 6-6 6" fill="none" stroke="#293c37" stroke-width="2"/>`;break;
 case 'monday':case 'tuesday':{const index=id==='monday'?0:1;shape=`<rect x="31" y="43" width="190" height="140" rx="4" fill="#fbf7eb" stroke="#293c37" stroke-width="2"/><path d="M31 43h190v31H31z" fill="#aa4f36"/>${['man','tir','ons','tor','fre'].map((day,i)=>`<rect x="${37+i*37}" y="88" width="31" height="74" fill="${i===index?'#bccba9':'#eee7d7'}"/><text x="${52+i*37}" y="109" font-family="Arial" font-size="10" text-anchor="middle" fill="#293c37">${day}</text>${i===index?`<circle cx="${52+i*37}" cy="139" r="9" fill="#aa4f36"/>`:''}`).join('')}<text x="126" y="64" font-family="Arial" font-size="11" text-anchor="middle" fill="#fff8e9">${id==='monday'?'MANDAG':'TIRSDAG'}</text>`;break;}
 case 'person':shape=person;break;
 case 'pair':shape=`<g transform="translate(-29 16) scale(.8)">${person}</g><g transform="translate(82 23) scale(.7)">${person}</g>`;break;
 case 'read':shape=person+`<g transform="translate(39 73) scale(.68)">${book(70,58,110,100)}</g><path d="M89 130l14 24M158 130l-14 24" stroke="#d9b995" stroke-width="10" stroke-linecap="round"/>`;break;
 case 'write':shape=person+`<path d="M35 160h181v13H35z" fill="#ba9f7b" stroke="#293c37"/><path d="M65 155l17-42M167 146l-17-27" stroke="#d9b995" stroke-width="11" stroke-linecap="round"/><path d="M86 151h63l-4-28H94z" fill="#fffdf3" stroke="#293c37"/><path d="M154 120l-12 31" stroke="#b45335" stroke-width="4"/>`;break;
 case 'school':shape=`<path d="M31 81l94-52 94 52" fill="#bc6f53" stroke="#293c37" stroke-width="2"/><path d="M40 82h171v113H40z" fill="#d3c8aa" stroke="#293c37" stroke-width="2"/><path d="M105 195v-59h40v59" fill="#5d817c" stroke="#293c37" stroke-width="2"/><path d="M61 101h27v26H61zM163 101h27v26h-27zM61 147h27v26H61zM163 147h27v26h-27z" fill="#dde8df" stroke="#293c37" stroke-width="2"/><path d="M23 197h206" stroke="#293c37" stroke-width="2"/>`;break;
 case 'book-on-table':shape=table+`<path d="M79 83h83v16H79z" fill="#aa4f36" stroke="#293c37" stroke-width="2"/><path d="M83 87h74v8H83z" fill="#f7efdd"/>`;break;
 case 'book-under-table':shape=table+`<path d="M77 170h83v16H77z" fill="#aa4f36" stroke="#293c37" stroke-width="2"/><path d="M81 174h74v8H81z" fill="#f7efdd"/>`;break;
 case 'book-in-bag':shape=`<g transform="translate(10 -9)">${book(86,28,77,105)}</g><path d="M67 100h117v74q0 22-25 22H91q-24 0-24-22z" fill="#798d83" stroke="#293c37" stroke-width="2"/><rect x="84" y="133" width="82" height="43" rx="9" fill="#b5c1ac" stroke="#293c37"/><path d="M70 100q55 19 111 0" stroke="#293c37" stroke-width="2" fill="none"/>`;break;
 case 'eat':shape=person+`<path d="M31 160h188v13H31z" fill="#ba9f7b" stroke="#293c37"/><ellipse cx="127" cy="155" rx="40" ry="9" fill="#f7f1e4" stroke="#293c37"/><path d="M102 147l8-23h33l11 23z" fill="#ce965a" stroke="#293c37"/><path d="M80 129l20-30M103 104l10-28" stroke="#d9b995" stroke-width="10" stroke-linecap="round"/><path d="M110 76l4-14" stroke="#293c37" stroke-width="3"/>`;break;
 case 'clock8':case 'clock12':case 'clock18':{const hour=id==='clock8'?8:id==='clock12'?12:6,angle=hour*Math.PI/6;shape=`<circle cx="125" cy="110" r="83" fill="#fbf7eb" stroke="#293c37" stroke-width="3"/>${Array.from({length:12},(_,i)=>{const a=i*Math.PI/6;return `<path d="M${125+71*Math.sin(a)} ${110-71*Math.cos(a)}l${-6*Math.sin(a)} ${6*Math.cos(a)}" stroke="#8b8e7b" stroke-width="2"/>`;}).join('')}<text x="125" y="50" text-anchor="middle" font-family="Arial" font-size="12" fill="#293c37">12</text><text x="186" y="114" font-family="Arial" font-size="12" fill="#293c37">3</text><text x="125" y="181" text-anchor="middle" font-family="Arial" font-size="12" fill="#293c37">6</text><text x="57" y="114" font-family="Arial" font-size="12" fill="#293c37">9</text><path d="M125 110V59M125 110L${125+38*Math.sin(angle)} ${110-38*Math.cos(angle)}" stroke="#293c37" stroke-width="4" stroke-linecap="round"/><circle cx="125" cy="110" r="5" fill="#aa4f36"/>`;break;}
 case 'calendar':shape=`<rect x="43" y="38" width="165" height="155" rx="5" fill="#fbf7eb" stroke="#293c37" stroke-width="2"/><path d="M43 38h165v39H43z" fill="#aa4f36"/><path d="M77 27v24M174 27v24" stroke="#293c37" stroke-width="5" stroke-linecap="round"/>${[0,1,2].map(r=>[0,1,2,3,4].map(c=>`<rect x="${60+c*28}" y="${92+r*28}" width="15" height="14" rx="1" fill="${r===1&&c===1?'#b7c8b5':'#e1d8c3'}"/>`).join('')).join('')}`;break;
 default:shape=book();
 }
 return `<svg viewBox="0 0 250 225" ${decorative?'aria-hidden="true"':`role="img" aria-label="${ILLUSTRATION_NAMES[id]||'illustrasjon'}"`} xmlns="http://www.w3.org/2000/svg"><ellipse cx="125" cy="207" rx="82" ry="5" fill="#e5ddcb"/>${shape}</svg>`;
}
